import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 2 Thirteen equals one","description":"学习 过去进行时与突发事件，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 2 Thirteen equals one","description":"学习 过去进行时与突发事件，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 过去进行时与突发事件，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 1 A puma at large","link":"/life/english/new-concept/book-3/unit-01/lesson-001"},"next":{"text":"第三册：培养技能 · Lesson 3 An unknown goddess","link":"/life/english/new-concept/book-3/unit-01/lesson-003"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 1 A puma at large","link":"/life/english/new-concept/book-3/unit-01/lesson-001"},"next":{"text":"第三册：培养技能 · Lesson 3 An unknown goddess","link":"/life/english/new-concept/book-3/unit-01/lesson-003"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-002.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-002.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-002.md"};function l(r,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-2-thirteen-equals-one" tabindex="-1">第三册：培养技能 · Lesson 2 Thirteen equals one <a class="header-anchor" href="#第三册-培养技能-·-lesson-2-thirteen-equals-one" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 2 Thirteen equals one&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕钟表故障和意外声响组织叙事，学习先交代环境，再把读者带到突然发生的事件。练习同时区分持续动作与短暂动作，避免把故事所有动词都写成进行时；复述时要清楚说明谁正在做什么、什么事情打断了他，以及后来发现了什么。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>chime</td><td>/tʃaɪm/</td><td>v.</td><td>鸣响</td><td>the clock chimed</td></tr><tr><td>repair</td><td>/rɪˈpeə/</td><td>v.</td><td>修理</td><td>repair a clock</td></tr><tr><td>mechanism</td><td>/ˈmekənɪzəm/</td><td>n.</td><td>机械装置</td><td>a simple mechanism</td></tr><tr><td>interrupt</td><td>/ˌɪntəˈrʌpt/</td><td>v.</td><td>打断</td><td>interrupt a conversation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in the middle of — 在某活动或时段中间</li><li>go wrong — 出故障或出现问题</li></ul><h2 id="语法讲解-过去进行时与突发事件" tabindex="-1">语法讲解：过去进行时与突发事件 <a class="header-anchor" href="#语法讲解-过去进行时与突发事件" aria-label="Permalink to &quot;语法讲解：过去进行时与突发事件&quot;">​</a></h2><p>过去进行时由 was 或 were 加动词 ing 构成，表示过去某一时刻正在展开的动作，常作为故事背景。一般过去时通常推进事件，说明一个动作发生或完成。when 后可以出现打断背景的短动作，while 常引出持续的背景，但二者并非机械地对应固定时态。know、believe 等状态动词通常不用进行时；如果叙述的是先后完成的动作，应直接使用一般过去时，不必为了显得生动而把每个动词都改为进行时。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I was checking the clock when a loose screw fell onto the floor.</p></blockquote><p>我正在检查钟表，突然一颗松动的螺丝掉到了地板上。</p><p>was checking 提供背景，fell 引入一个短暂的新事件；when 连接两者。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I was knowing the answer 不适合表达当时知道答案，应写 I knew the answer；进行时强调过程而非单纯过去时间。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读示范时在第一句后稍停，突出 suddenly；回听录音，检查 cleaning 的尾音和 flew 的长元音是否清楚。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Nora was cleaning an old alarm clock. A tiny spring suddenly flew across the desk. She found it inside an empty cup.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句维修中的意外，先给持续背景，再给突发事件，最后给结果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>进行时设置场景，两个一般过去时动词按顺序推进故事。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：We ___ dinner when the bell rang.（were having/had had）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were having</p><p><strong>解析：</strong> 本题强调铃响时正在吃饭。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句哪个动作推进故事？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> a loose screw fell onto the floor</p><p><strong>解析：</strong> fell 描写突然发生的新事件。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改正：He were repairing the clock.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He was repairing the clock.</p><p><strong>解析：</strong> 单数 he 与 was 搭配。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去进行时与突发事件。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-001">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-003">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=a(i,[["render",l]]);export{u as __pageData,k as default};
